CREATE TABLE IF NOT EXISTS cfo_exp_row (id BIGSERIAL PRIMARY KEY, card_id BIGINT NOT NULL REFERENCES form_card(id) ON DELETE CASCADE, code_cfo INT NOT NULL, code_pl INT NOT NULL, legal_entity TEXT NOT NULL DEFAULT '', cfo TEXT NOT NULL DEFAULT '', group_pl TEXT NOT NULL DEFAULT '', expense TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', country_company TEXT NOT NULL DEFAULT '', comment TEXT NOT NULL DEFAULT '', UNIQUE(card_id,code_cfo,code_pl,legal_entity));
CREATE TABLE IF NOT EXISTS cfo_exp_value (id BIGSERIAL PRIMARY KEY,row_id BIGINT NOT NULL REFERENCES cfo_exp_row(id) ON DELETE CASCADE,scenario TEXT NOT NULL,year INT NOT NULL,month INT NOT NULL CHECK (month BETWEEN 1 AND 12),amount NUMERIC(18,2),updated_by BIGINT,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(row_id,scenario,year,month));
CREATE INDEX IF NOT EXISTS cfo_exp_row_card ON cfo_exp_row(card_id); CREATE INDEX IF NOT EXISTS cfo_exp_value_row ON cfo_exp_value(row_id);
